<?php use App\Core\Csrf;use App\Core\Database;
$appointments=Database::query("SELECT a.id,a.appointment_date,a.service,p.hn,p.full_name FROM appointments a JOIN patients p ON p.id=a.patient_id WHERE a.status='approved' ORDER BY a.appointment_date")->fetchAll();
$items=Database::query('SELECT t.*,a.appointment_date,a.service,p.full_name patient_name,u.full_name dentist_name FROM treatments t JOIN appointments a ON a.id=t.appointment_id JOIN patients p ON p.id=a.patient_id JOIN dentists d ON d.id=a.dentist_id LEFT JOIN users u ON u.id=d.user_id ORDER BY t.treated_at DESC')->fetchAll();page_header('วินิจฉัยและการรักษา','บันทึกผลการรักษาและค่าใช้จ่าย');?>
<details class="form-panel crud-form" open><summary>＋ สร้างบันทึกการรักษา</summary><form method="post"><input type="hidden" name="action" value="treatment_save"><?=Csrf::field()?><div class="form-grid"><label class="full">นัดหมาย<select name="appointment_id" required><?php foreach($appointments as $a):?><option value="<?=$a['id']?>"><?=htmlspecialchars($a['appointment_date'].' · '.$a['hn'].' '.$a['full_name'].' · '.$a['service'])?></option><?php endforeach?></select></label><label>วินิจฉัย<input name="diagnosis" required></label><label>การรักษา<input name="treatment_detail" required></label><label>ตำแหน่งฟัน<input name="tooth_position"></label><label>ค่าใช้จ่าย<input type="number" min="0" step="0.01" name="cost"></label></div><button class="primary-button fit">บันทึกและปิดงาน</button></form></details>
<section class="panel"><?php data_table(['วันที่','ผู้ป่วย','วินิจฉัย','การรักษา','ทันตแพทย์','ค่าใช้จ่าย'],array_map(fn($r)=>[$r['appointment_date'],$r['patient_name'],$r['diagnosis'],$r['treatment_detail'],$r['dentist_name'],number_format((float)$r['cost'],2)],$items));?></section>
